def strategy(history, rng):
    n = len(history)
    if n < 2:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_d = opp.count('D')
    my_d = me.count('D')
    last_me, last_opp = history[-1]

    # Punish consecutive defections
    if n >= 2 and opp[-1] == 'D' and opp[-2] == 'D':
        return 'D'

    if opp_d == n:
        return 'D'

    if opp_d > n * 0.6:
        return 'D'

    if opp_d == 0:
        if n < 20:
            return 'C'
        if last_me == 'C':
            return 'D'
        else:
            return 'C'

    if opp_d < n * 0.1:
        recent_d = sum(1 for o in opp[-5:] if o == 'D')
        if recent_d == 0:
            if n == 99:
                return 'D'
            return 'C'

    after_c_total = 0
    after_c_d = 0
    for i in range(n - 1):
        if me[i] == 'C':
            after_c_total += 1
            if opp[i + 1] == 'D':
                after_c_d += 1
    if after_c_total >= 5:
        p_d_after_c = after_c_d / after_c_total
        if p_d_after_c > 0.3:
            return 'D'

    if last_opp == 'D':
        if last_me == 'C':
            if opp_d < n * 0.3:
                return 'C'
            return 'D'
        else:
            if opp_d < n * 0.5:
                return 'C'
            return 'D'
    else:
        if last_me == 'D':
            return 'C'
        else:
            if n == 99:
                return 'D'
            return 'C'
